-- Secuencia de bloques de un programa RFT: lista ordenada de
-- { fase, origen, destino } (ej. entrenamiento B→A, entrenamiento C→B,
-- transformacion_funciones C→A). La toma de datos recomienda el primer paso
-- no dominado en el grupo. Sin secuencia se usa la regla genérica
-- (entrenamiento lineal, tests mutuos y combinatorios). Se rellenan las del
-- currículo a partir de su apartado «Registro en la app» y se copian a los
-- programas ya importados.
begin;

alter table programas_base add column secuencia_rft jsonb;
alter table programas_alumno add column secuencia_rft jsonb;

-- La secuencia también es contenido de la plantilla: si cambia, las copias
-- del PEI reciben el aviso de actualización
create or replace function programas_base_marcar_contenido()
returns trigger language plpgsql set search_path = public as $$
begin
  if (new.nombre, new.objetivo, new.materiales, new.instrucciones_terapeuta, new.ayudas_posibles,
      new.ensayos_por_bloque, new.bloques_para_dominio, new.porcentaje_dominio,
      new.tipo_respuesta, new.opciones_respuesta, new.respuesta_por_fase, new.secuencia_rft)
     is distinct from
     (old.nombre, old.objetivo, old.materiales, old.instrucciones_terapeuta, old.ayudas_posibles,
      old.ensayos_por_bloque, old.bloques_para_dominio, old.porcentaje_dominio,
      old.tipo_respuesta, old.opciones_respuesta, old.respuesta_por_fase, old.secuencia_rft) then
    new.contenido_actualizado_at := now();
  end if;
  return new;
end;
$$;

update programas_base set secuencia_rft = '[{"fase": "entrenamiento", "origen": "A", "destino": "B"}, {"fase": "test_mutuo", "origen": "B", "destino": "A"}]'::jsonb where clinica_id is null and tipo = 'rft' and nombre = 'Seguir Instrucciones para Dos Acciones';
